import{_ as s,o as n,c as a,a2 as o}from"./chunks/framework.DiXyETtc.js";const h=JSON.parse('{"title":"Stores and repositories","description":"","frontmatter":{},"headers":[],"relativePath":"repositories/index.md","filePath":"repositories/index.md","lastUpdated":1795620027000}'),t={name:"repositories/index.md"};function r(c,e,i,l,d,p){return n(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="stores-and-repositories" tabindex="-1">Stores and repositories <a class="header-anchor" href="#stores-and-repositories" aria-label="Permalink to &quot;Stores and repositories&quot;">​</a></h1><p>Runs, steps, checkpoints, effect results, artifacts, agent state, locks, idempotency keys, tool-limit uses and agent revision markers sit behind services: the engine receives a <code>RunService</code> (<code>runService</code>), a <code>StepService</code> (<code>stepService</code>), a <code>CheckpointService</code> (<code>checkpointService</code>), an <code>EffectService</code> (<code>effectService</code>), an <code>ArtifactService</code> (<code>artifactService</code>), a <code>StateService</code> (<code>stateService</code>), a <code>LockService</code> (<code>lockService</code>), an <code>IdempotencyService</code> (<code>idempotencyService</code>) and an <code>AgentRevisionService</code> (<code>agentRevisionService</code>) that hold every rule (lineage, the update guards, <code>updatedAt</code>, the claim lease, the list queries, the highest checkpoint, insert-if-absent artifacts, the keyed artifact that keeps its id, the lease and claim expiry) over the repository ports of <code>@chamvi/store</code>. A port only stores, reads, locks a row and runs a query:</p><table tabindex="0"><thead><tr><th>Port (<code>@chamvi/store</code>)</th><th>Holds</th><th>Implementations</th></tr></thead><tbody><tr><td><code>IRunRepository</code></td><td>Runs: the generic entity port (<code>findOneById</code>, <code>findMany(query)</code>, <code>create</code>/<code>save</code>, <code>transaction(fn)</code>, ...) plus <code>findByWaitKind(kind, query)</code></td><td><code>MemoryRunRepository</code> (<code>@chamvi/store-memory</code>), <code>DatabaseRunRepository</code> (<code>@chamvi/store-db</code>)</td></tr><tr><td><code>IStepRepository</code></td><td>Append-only steps per run</td><td><code>MemoryStepRepository</code>, <code>DatabaseStepRepository</code></td></tr><tr><td><code>ICheckpointRepository</code></td><td>One checkpoint row per run</td><td><code>MemoryCheckpointRepository</code>, <code>DatabaseCheckpointRepository</code></td></tr><tr><td><code>IEffectRepository</code></td><td>Recorded effect results by key (<code>upsert</code> replaces by key)</td><td><code>MemoryEffectRepository</code>, <code>DatabaseEffectRepository</code></td></tr><tr><td><code>IArtifactRepository</code></td><td>Files of a run: metadata, plus <code>readData(id)</code> for the bytes</td><td><code>MemoryArtifactRepository</code>, <code>DatabaseArtifactRepository</code></td></tr><tr><td><code>IStateRepository</code>, <code>IStateDocumentRepository</code></td><td>Per-agent keys and collection documents, plus <code>findContaining(agent, collection, where, page)</code></td><td><code>MemoryStateRepository</code>, <code>MemoryStateDocumentRepository</code>, <code>DatabaseStateRepository</code>, <code>DatabaseStateDocumentRepository</code></td></tr><tr><td><code>ILockRepository</code></td><td>Keyed leases (<code>Lock</code>: <code>key</code>, <code>owner</code>, <code>expiresAt</code>, <code>token</code>), plus <code>removeExpiredBy(time)</code> and <code>nextToken()</code> (a fencing token strictly above every one issued before, for any key, and at least the wall clock in microseconds); <code>LockService</code> takes over an expired lease and reads the clock after the locked row, and <code>acquire</code> resolves the lease&#39;s token (<code>undefined</code> when refused)</td><td><code>MemoryLockRepository</code>, <code>DatabaseLockRepository</code></td></tr><tr><td><code>IIdempotencyRepository</code></td><td>Intake keys (<code>IdempotencyKey</code>: <code>scope</code>, <code>key</code>, <code>runId</code>, <code>expiresAt</code>), plus <code>removeExpiredBy(time)</code>; <code>IdempotencyService.claim</code>: the first caller wins</td><td><code>MemoryIdempotencyRepository</code>, <code>DatabaseIdempotencyRepository</code></td></tr><tr><td><code>ILimitRepository</code></td><td>Counted tool-limit uses (<code>LimitUse</code>: <code>scope</code>, <code>key</code>, <code>weight</code>, <code>createdAt</code>, unique by <code>(scope, key)</code>), plus <code>sumWeight(scope, since)</code> and <code>removeCreatedBefore(time)</code>; <code>LimitService</code> (optional <code>limitService</code> of the engine): <code>used(scope, windowMs)</code>, <code>record</code> (insert-if-absent, created now), <code>purgeExpired</code></td><td><code>MemoryLimitRepository</code>, <code>DatabaseLimitRepository</code></td></tr><tr><td><code>IAgentRevisionRepository</code></td><td>One revision marker per <a href="/guide/agent-folders">folder agent</a> (<code>AgentRevisionRecord</code>: <code>{ agent, hash, changedAt }</code> and its storage <code>id</code>, no code); <code>AgentRevisionService</code>: <code>findOne</code>, <code>save</code> (upsert by agent), <code>delete</code> (a missing one is a no-op), <code>find</code> (agent code-point order)</td><td><code>MemoryAgentRevisionRepository</code>, <code>DatabaseAgentRevisionRepository</code></td></tr><tr><td><code>IConnectionRepository</code></td><td>Connection rows (<code>ConnectionRecord</code>: sealed entries and the wrapped data key, never a plaintext or a key) with <code>entries</code> and <code>secrets</code> as child repositories bound to its transactions, plus <code>findFence(lock)</code>, the lease&#39;s lock row read locked after the connection row. <code>ConnectionService</code> (optional, <code>connectionService</code>) holds every rule</td><td><code>MemoryConnectionRepository</code>, <code>DatabaseConnectionRepository</code></td></tr><tr><td><code>IConversationRepository</code></td><td>Conversation rows (scope id, identity key, generation, active run and its snapshot) with <code>items</code>, <code>notes</code> and <code>operations</code> as child repositories bound to its transactions; <code>CONVERSATION_ITEM_STORED_ORDER</code> sorts items in transcript order. <code>ConversationService</code> (optional, <code>conversationService</code>) holds every rule: <code>resolve</code>, <code>beginTurn</code>, <code>endTurn</code>, <code>prepareEmit</code>, <code>confirmEmit</code>, <code>applyNote</code>, <code>reset</code>, <code>delete</code>, <code>prune</code>, and the reads</td><td><code>MemoryConversationRepository</code>, <code>DatabaseConversationRepository</code></td></tr></tbody></table><p>There is no store aggregate: the engine takes each service by name. Every service has an interface (<code>IRunService</code>, <code>IStepService</code>, ..., <code>IConversationService</code>), and the engine, the channels and the HTTP API are typed by it: any object that satisfies the interface can stand in for the class, with or without a repository behind it (a fake in a test, a wrapper that records or fails calls). <code>createConnectionVault()</code> takes the connection service and a <code>lockService</code> on the same lock storage, e.g. for the <a href="/deployment/whatsapp#session-store">WhatsApp session store</a>. Pass the services as <code>new Engine({ runService, stepService, checkpointService, effectService, artifactService, stateService, lockService, idempotencyService, agentRevisionService, conversationService, agents })</code>; use <code>engine.runService.findOne(id)</code> or <code>engine.stateService.findOne(agent, key)</code> for direct access. Conversation storage alone does not enable memory: configure <code>conversations: { authorize, limits? }</code> on the engine and opt agents in.</p><h2 id="updating-existing-callers" tabindex="-1">Updating existing callers <a class="header-anchor" href="#updating-existing-callers" aria-label="Permalink to &quot;Updating existing callers&quot;">​</a></h2><p>The <a href="/guide/upgrading">upgrade guide</a> lists every renamed and removed storage export with its replacement.</p><h2 id="query-methods" tabindex="-1">Query methods <a class="header-anchor" href="#query-methods" aria-label="Permalink to &quot;Query methods&quot;">​</a></h2><p><code>findOne(...)</code> returns one record or <code>undefined</code>. <code>find(...)</code> returns the repository&#39;s existing collection shape: run queries return <code>{ data, total }</code>, while steps, artifacts, state and agent revisions return arrays. Conversation item/note queries return <code>{ data, total }</code> through <code>findItems</code> and <code>findNotes</code>.</p><p>The matching <code>OrFail</code> method returns the same result when it exists. <code>findOneOrFail(...)</code> throws for <code>undefined</code>; stored state values such as <code>null</code>, <code>false</code>, <code>0</code> and <code>&#39;&#39;</code> are valid results. <code>findOrFail(...)</code> throws when the selected array or page is empty, including a run query with <code>limit: 0</code> or an offset beyond the last result even when <code>total</code> is nonzero. Query validation is unchanged: conversation queries require <code>limit &gt;= 1</code>, so their <code>limit: 0</code> is a validation error. Qualified queries follow the same rule: <code>findDocumentsOrFail</code>, <code>findItemsOrFail</code>, <code>findNotesOrFail</code> and <code>findOneNoteOrFail</code>.</p><p>A missing single run or artifact uses <code>RunNotFoundError</code> or <code>ArtifactNotFoundError</code>; other missing repository results use <code>RepositoryNotFoundError</code>. Backend failures and validation errors pass through unchanged. Leases and mutations retain their domain operations, such as <code>claim</code>, <code>renewClaim</code> and <code>beginTurn</code>.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> run = </span><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> engine.runService.findOneOrFail(runId);</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> { data, total } = </span><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> engine.runService.find({ agent: run.agent, limit: </span><span style="color:#E7C58C;">20</span><span style="color:#E3E5EA;"> });</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> artifacts = </span><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> engine.artifactService.find(runId);</span></span></code></pre></div><h2 id="rules-every-repository-keeps" tabindex="-1">Rules every repository keeps <a class="header-anchor" href="#rules-every-repository-keeps" aria-label="Permalink to &quot;Rules every repository keeps&quot;">​</a></h2><p>A repository stores, reads, locks a row and runs a query; it decides nothing. The <a href="/repositories/writing-a-repository#prove-it-with-the-contract-suite">port suites</a> check each rule on your backend.</p><ol><li><strong>Store as given.</strong> No status, owner or revision compare, no limit, default, time stamp, derived field or choice of domain error, and no clock: the services decide and hand the repository the finished row.</li><li><strong>No aliasing.</strong> Values are copied in and out. Mutating an object after passing it to a repository, or one a repository returned, never changes what it holds.</li><li><strong>Transactions.</strong> <code>transaction(fn)</code> hands <code>fn</code> a repository bound to the transaction; a single-row read there (<code>findOneById</code>, <code>findOneBy</code>) locks the row until the transaction ends, so two callers never interleave between a read and its save, also across processes. A throw rolls everything back.</li><li><strong>Six storage errors</strong>, each with the entity&#39;s label and a fixed message, never a value: <code>EntityNotFoundError</code>, <code>EntityConflictError</code> (a taken key or unique value), <code>EntityRelationError</code> (a missing referenced row, or a removed row another references), <code>EntityDeadlockError</code>, <code>EntityQueryError</code> (a where with an <code>undefined</code> value, an empty <code>removeManyBy</code>, an operation the port does not offer), <code>EntityInvalidError</code> (a value the table refuses: a missing required column, a failed check, a value too long).</li><li><strong>Orderings the storage owns.</strong> <code>findMany</code> sorts strings by code point (case sensitive); steps and conversation items keep a storage key in the order they were stored (<code>STEP_STORED_ORDER</code>, <code>CONVERSATION_ITEM_STORED_ORDER</code>).</li></ol><h2 id="rules-the-services-keep" tabindex="-1">Rules the services keep <a class="header-anchor" href="#rules-the-services-keep" aria-label="Permalink to &quot;Rules the services keep&quot;">​</a></h2><ol><li><strong>One expiry rule.</strong> A claim, key or lock created at time <code>T</code> with <code>ttlMs</code> is expired at exactly <code>T + ttlMs</code> and can be taken over at that instant.</li><li><strong>Time comes from the clock.</strong> Every service that compares time takes an <code>IClock</code> and reads it after its locked read, never the database&#39;s clock, so tests can drive time and replicas agree on one rule.</li><li><strong>Atomic means atomic across callers.</strong> <code>runService.create</code>, <code>runService.claim</code>, <code>runService.renewClaim</code>, <code>idempotencyService.claim</code>, <code>lockService.acquire</code>, <code>artifactService.create</code> and <code>artifactService.save</code> hold under concurrency, also across processes.</li><li><strong>Ordering.</strong> <code>runService.find</code> orders by <code>createdAt</code> ascending, ties broken by <code>id</code> ascending, or both descending with <code>order: &#39;desc&#39;</code> (newest first); <code>total</code> ignores <code>limit</code> and <code>offset</code>. <code>artifactService.find</code> orders the same way. <code>agentRevisionService.find</code> orders by agent name in code-point order.</li><li><strong>Guards throw.</strong> <code>runService.update</code> throws <code>InvalidRunStateError</code> when <code>expectStatus</code> does not match, or when <code>expectOwner</code> is given and the claim is absent or held by another owner (expiry is not checked there: a lease is lost once taken over), or when <code>expectWaitId</code> is given and the run&#39;s wait id differs or it has no wait point. It throws <code>RunNotFoundError</code> for an unknown run.</li><li><strong>Checkpoints.</strong> <code>checkpointService.save</code> keeps the highest <code>stepIndex</code>; an equal index replaces.</li><li><strong>State filters.</strong> <code>stateService.findDocuments</code> <code>where</code> matches top-level fields by equality and lists by document id in code-point order.</li><li><strong>Run references.</strong> <code>stepService.create</code>, <code>checkpointService.save</code> and <code>conversationService.beginTurn</code> for a run the store does not hold throw <code>RunNotFoundError</code> and write nothing (the repository reports <code>EntityRelationError</code>).</li><li><strong>Artifacts.</strong> <code>artifactService.create</code> resolves <code>false</code> and keeps the stored metadata and bytes when the id exists, or when <code>key</code> is given and the run already holds an artifact under that key. <code>artifactService.save</code> is an atomic upsert by <code>(runId, key)</code> and resolves the stored metadata: an absent key inserts the artifact as given, an existing one keeps its <code>id</code>, <code>agent</code> and <code>createdAt</code> and replaces <code>mediaType</code>, <code>filename</code> (a missing one removes it), <code>size</code> and the bytes. The key is private to the store: no read returns it, and <code>findOneByKey(runId, key)</code> is the only lookup by it. <code>read</code> returns a plain <code>Uint8Array</code> (no <code>Buffer</code> or other subclass); <code>findOne</code> and <code>find</code> return metadata only.</li></ol><h2 id="the-interfaces" tabindex="-1">The interfaces <a class="header-anchor" href="#the-interfaces" aria-label="Permalink to &quot;The interfaces&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#80858F;">/*</span></span>
<span class="line"><span style="color:#80858F;"> * Copyright (c) 2026.</span></span>
<span class="line"><span style="color:#80858F;"> * Author Peter Placzek (tada5hi)</span></span>
<span class="line"><span style="color:#80858F;"> * For the full copyright and license information,</span></span>
<span class="line"><span style="color:#80858F;"> * view the LICENSE file that was distributed with this source code.</span></span>
<span class="line"><span style="color:#80858F;"> */</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">import</span><span style="color:#8EA7FF;"> type</span><span style="color:#E3E5EA;"> { IQuery } </span><span style="color:#8EA7FF;">from</span><span style="color:#E7C58C;"> &#39;@rapiq/core&#39;</span><span style="color:#E3E5EA;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">/**</span></span>
<span class="line"><span style="color:#80858F;"> * A stored row: a plain object keyed by property name.</span></span>
<span class="line"><span style="color:#80858F;"> */</span></span>
<span class="line"><span style="color:#8EA7FF;">export</span><span style="color:#8EA7FF;"> type</span><span style="color:#E3E5EA;"> EntityRecord = Record&lt;string, any&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">/**</span></span>
<span class="line"><span style="color:#80858F;"> * A where of \`findOneBy\`, \`findManyBy\` and \`removeManyBy\`: each given</span></span>
<span class="line"><span style="color:#80858F;"> * property matches its value, \`null\` (a missing value) or, given an</span></span>
<span class="line"><span style="color:#80858F;"> * array, any of the array&#39;s values (a \`null\` in it matching a missing</span></span>
<span class="line"><span style="color:#80858F;"> * value); every given property must match. A</span></span>
<span class="line"><span style="color:#80858F;"> * property present with the value \`undefined\` is refused with</span></span>
<span class="line"><span style="color:#80858F;"> * \`EntityQueryError\` (omit it instead): a filter never silently widens.</span></span>
<span class="line"><span style="color:#80858F;"> */</span></span>
<span class="line"><span style="color:#8EA7FF;">export</span><span style="color:#8EA7FF;"> type</span><span style="color:#E3E5EA;"> EntityWhere&lt;T&gt; = {</span></span>
<span class="line"><span style="color:#E3E5EA;">    [K </span><span style="color:#8EA7FF;">in</span><span style="color:#8EA7FF;"> keyof</span><span style="color:#E3E5EA;"> T]?: T[K] | T[K][] | null;</span></span>
<span class="line"><span style="color:#E3E5EA;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">/**</span></span>
<span class="line"><span style="color:#80858F;"> * One page of \`findMany\`: the rows and the total of the whole selection.</span></span>
<span class="line"><span style="color:#80858F;"> */</span></span>
<span class="line"><span style="color:#8EA7FF;">export</span><span style="color:#8EA7FF;"> type</span><span style="color:#E3E5EA;"> EntityFindManyResult&lt;T&gt; = {</span></span>
<span class="line"><span style="color:#E3E5EA;">    data: T[];</span></span>
<span class="line"><span style="color:#E3E5EA;">    meta: {</span></span>
<span class="line"><span style="color:#E3E5EA;">        total: number;</span></span>
<span class="line"><span style="color:#E3E5EA;">        limit?: number;</span></span>
<span class="line"><span style="color:#E3E5EA;">        offset?: number;</span></span>
<span class="line"><span style="color:#E3E5EA;">    };</span></span>
<span class="line"><span style="color:#E3E5EA;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">/**</span></span>
<span class="line"><span style="color:#80858F;"> * The generic repository port of one entity. A repository decides</span></span>
<span class="line"><span style="color:#80858F;"> * nothing: it stores, reads, locks a row, runs a query and reports</span></span>
<span class="line"><span style="color:#80858F;"> * \`EntityNotFoundError\`, \`EntityConflictError\`, \`EntityRelationError\`,</span></span>
<span class="line"><span style="color:#80858F;"> * \`EntityDeadlockError\` or \`EntityQueryError\`; status compares, limits, defaults and time stamps</span></span>
<span class="line"><span style="color:#80858F;"> * belong to the service using it.</span></span>
<span class="line"><span style="color:#80858F;"> */</span></span>
<span class="line"><span style="color:#8EA7FF;">export</span><span style="color:#8EA7FF;"> interface</span><span style="color:#E3E5EA;"> IEntityRepository&lt;T </span><span style="color:#8EA7FF;">extends</span><span style="color:#E3E5EA;"> EntityRecord = EntityRecord&gt; {</span></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Run a rapiq query (fields, filters, sort, pagination) over the</span></span>
<span class="line"><span style="color:#80858F;">     * entity. Inside \`transaction()\` it locks none of the rows it returns:</span></span>
<span class="line"><span style="color:#80858F;">     * a service that changes a listed row reads it again with a single-row</span></span>
<span class="line"><span style="color:#80858F;">     * read first. A row read with a field selection holds those fields</span></span>
<span class="line"><span style="color:#80858F;">     * only: \`save\` of it writes what changed, \`upsert\` and \`upsertMany\`</span></span>
<span class="line"><span style="color:#80858F;">     * refuse it (\`EntityQueryError\`), by object identity as \`save\` decides.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    findMany(query: IQuery): Promise&lt;EntityFindManyResult&lt;T&gt;&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * The row with this primary key, or \`null\`. Inside \`transaction()\` the</span></span>
<span class="line"><span style="color:#80858F;">     * row read through the handed-in repository is locked until the</span></span>
<span class="line"><span style="color:#80858F;">     * transaction ends. An \`undefined\` or \`null\` id is refused with</span></span>
<span class="line"><span style="color:#80858F;">     * \`EntityQueryError\`.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    findOneById(id: string): Promise&lt;T | null&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * The one row matching the where, or \`null\`. Inside \`transaction()\`</span></span>
<span class="line"><span style="color:#80858F;">     * the row read through the handed-in repository is locked until the</span></span>
<span class="line"><span style="color:#80858F;">     * transaction ends.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    findOneBy(where: EntityWhere&lt;T&gt;): Promise&lt;T | null&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Every row matching the where (\`EntityWhere\`), however many values</span></span>
<span class="line"><span style="color:#80858F;">     * an array holds. Inside \`transaction()\` it locks none of the rows it</span></span>
<span class="line"><span style="color:#80858F;">     * returns: a service that changes a listed row reads it again with a</span></span>
<span class="line"><span style="color:#80858F;">     * single-row read first.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    findManyBy(where: EntityWhere&lt;T&gt;): Promise&lt;T[]&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * A new entity object; nothing is stored. \`save()\` inserts it.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    create(data: Partial&lt;T&gt;): T;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Copy \`data\` onto \`entity\` and return it; nothing is stored.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    merge(entity: T, data: Partial&lt;T&gt;): T;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Insert or update, decided by object identity: an entity object</span></span>
<span class="line"><span style="color:#80858F;">     * returned by \`create()\` is inserted (\`EntityConflictError\` if its key</span></span>
<span class="line"><span style="color:#80858F;">     * exists), an entity object returned by a read is updated (its changed</span></span>
<span class="line"><span style="color:#80858F;">     * properties only). A spread copy of a created entity is neither and</span></span>
<span class="line"><span style="color:#80858F;">     * counts as an update. Resolves the stored row as a read returns it</span></span>
<span class="line"><span style="color:#80858F;">     * (a new object, itself marked as read).</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    save(entity: T): Promise&lt;T&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Insert, or replace the row with the same key; no condition. Resolves</span></span>
<span class="line"><span style="color:#80858F;">     * the stored row as a read returns it. A row \`findMany\` read with a</span></span>
<span class="line"><span style="color:#80858F;">     * field selection is refused (\`EntityQueryError\`): it would clear the</span></span>
<span class="line"><span style="color:#80858F;">     * fields it lacks.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    upsert(entity: T): Promise&lt;T&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * \`upsert\` of each entity, in one transaction (all or nothing), in as</span></span>
<span class="line"><span style="color:#80858F;">     * few statements as the driver allows, however many there are: no</span></span>
<span class="line"><span style="color:#80858F;">     * condition, a later entity of the same key replaces an earlier one.</span></span>
<span class="line"><span style="color:#80858F;">     * An empty array stores nothing. Resolves the stored rows as reads</span></span>
<span class="line"><span style="color:#80858F;">     * return them, in input order.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    upsertMany(entities: T[]): Promise&lt;T[]&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Delete the entity&#39;s row.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    remove(entity: T): Promise&lt;void&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Delete the rows of every given entity.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    removeMany(entities: T[]): Promise&lt;void&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Delete every row matching the where (\`EntityWhere\`) without</span></span>
<span class="line"><span style="color:#80858F;">     * reading them out, and resolve how many it deleted. An empty where is</span></span>
<span class="line"><span style="color:#80858F;">     * refused with \`EntityQueryError\`: there is no remove-all form. A row another entity references is refused as by</span></span>
<span class="line"><span style="color:#80858F;">     * \`remove\`, unless the reference removes or clears the referencing</span></span>
<span class="line"><span style="color:#80858F;">     * rows with it (the driver&#39;s schema decides).</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    removeManyBy(where: EntityWhere&lt;T&gt;): Promise&lt;number&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Check that every row \`data\` references exists, else</span></span>
<span class="line"><span style="color:#80858F;">     * \`EntityRelationError\` naming the referenced entity.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    validateRelations(data: Partial&lt;T&gt;): Promise&lt;void&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Check that no other row holds a unique value of \`data\`, else</span></span>
<span class="line"><span style="color:#80858F;">     * \`EntityConflictError\`; \`existing\` is the row being updated, which</span></span>
<span class="line"><span style="color:#80858F;">     * may hold its own values.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    checkUniqueness(data: Partial&lt;T&gt;, existing?: T): Promise&lt;void&gt;;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#80858F;">    /**</span></span>
<span class="line"><span style="color:#80858F;">     * Run \`fn\` in one transaction with a repository bound to it. Use only</span></span>
<span class="line"><span style="color:#80858F;">     * the handed-in repository inside \`fn\`: a call on the outer repository</span></span>
<span class="line"><span style="color:#80858F;">     * is not part of the transaction, and a write through it on a row the</span></span>
<span class="line"><span style="color:#80858F;">     * transaction holds waits for \`fn\` while \`fn\` waits for it, so neither</span></span>
<span class="line"><span style="color:#80858F;">     * ends. A single-row read on the handed-in repository</span></span>
<span class="line"><span style="color:#80858F;">     * (\`findOneById\`, \`findOneBy\`) locks that row until the transaction</span></span>
<span class="line"><span style="color:#80858F;">     * ends, a list read (\`findMany\`, \`findManyBy\`) locks nothing, so a</span></span>
<span class="line"><span style="color:#80858F;">     * service that changes a row reads it with a single-row read first. A</span></span>
<span class="line"><span style="color:#80858F;">     * throw rolls everything back, also the identity of entity objects</span></span>
<span class="line"><span style="color:#80858F;">     * saved in it: a retry saves them as the first attempt did. Await every</span></span>
<span class="line"><span style="color:#80858F;">     * call on the handed-in repository before \`fn\` settles: a call that</span></span>
<span class="line"><span style="color:#80858F;">     * runs after the transaction ended is refused with a storage error.</span></span>
<span class="line"><span style="color:#80858F;">     */</span></span>
<span class="line"><span style="color:#E3E5EA;">    transaction&lt;R&gt;(fn: (repository: this) </span><span style="color:#8EA7FF;">=&gt;</span><span style="color:#E3E5EA;"> Promise&lt;R&gt;): Promise&lt;R&gt;;</span></span>
<span class="line"><span style="color:#E3E5EA;">}</span></span></code></pre></div><h2 id="store-implementations" tabindex="-1">Store implementations <a class="header-anchor" href="#store-implementations" aria-label="Permalink to &quot;Store implementations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Store</th><th>Package</th><th>Status</th></tr></thead><tbody><tr><td><a href="/repositories/memory">Memory repositories</a></td><td><code>@chamvi/store-memory</code></td><td>Shipped. Development and tests</td></tr><tr><td><a href="/repositories/database">Database (store-db)</a></td><td><code>@chamvi/store-db</code></td><td>Shipped. PostgreSQL, production</td></tr></tbody></table><p>Redis is never required. Any store whose repositories pass the <a href="/repositories/writing-a-repository">port suites</a> of <code>@chamvi/test-kit</code> works with the engine.</p>`,21)])])}const u=s(t,[["render",r]]);export{h as __pageData,u as default};
